function mergeProgress(cloud, local){
  const merged={...base,...(cloud||{}),...(local||{})};
  for(const k of ['done','notes','books','media','reflections']) merged[k]={...((cloud||{})[k]||{}),...((local||{})[k]||{})};
  merged.done={...((cloud||{}).done||{}),...((local||{}).done||{})};
  for(const k of Object.keys(merged.done)) merged.done[k]=Boolean(((cloud||{}).done||{})[k]||((local||{}).done||{})[k]);
  const ideas=[...((cloud||{}).ideas||[]),...((local||{}).ideas||[])];
  const seen=new Set(); merged.ideas=ideas.filter(x=>{const id=[x.t||'',x.date||'',x.b||''].join('|');if(seen.has(id))return false;seen.add(id);return true;});
  merged.minutes=Math.max(Number((cloud||{}).minutes)||0,Number((local||{}).minutes)||0);
  merged.sessions=Math.max(Number((cloud||{}).sessions)||0,Number((local||{}).sessions)||0);
  return merged;
}
