async function handleSignedIn(user){
 orbitaUser=user;document.getElementById('authButton').style.display='none';document.getElementById('signOutButton').style.display='inline-block';setAuthStatus('Conectando à nuvem…');
 const {data,error}=await orbitaClient.from('orbita_progress').select('state').eq('user_id',user.id).maybeSingle();
 if(error){setAuthStatus('Erro ao carregar nuvem');console.error(error);throw new Error('Login efetuado, mas não foi possível ler o progresso. Confira se executou o SQL de configuração no Supabase.');}
 if(data?.state){applyingCloud=true;S=mergeProgress(data.state,S);try{localStorage.setItem(KEY,JSON.stringify(S));}finally{applyingCloud=false;}await syncStateToCloud();}
 else await syncStateToCloud();
 render(document.querySelector('[data-v].active')?.dataset.v||'home');
}
async function signOutOrbita(){if(!orbitaClient)return;await syncStateToCloud();const {error}=await orbitaClient.auth.signOut();if(error){toast('Não foi possível sair.');return;}orbitaUser=null;document.getElementById('authButton').style.display='inline-block';document.getElementById('signOutButton').style.display='none';setAuthStatus('Progresso salvo neste navegador');toast('Você saiu da conta.');}
if(orbitaClient){orbitaClient.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){orbitaUser=null;}});orbitaClient.auth.getSession().then(({data})=>{if(data.session?.user)handleSignedIn(data.session.user).catch(e=>{console.error(e);setAuthStatus('Erro de sincronização');});});}

