function render(v="home"){let a=$("#app"),next=D.calendar.find(x=>!S.done[x.day])||D.calendar[D.calendar.length-1];

if(v==="home"){a.innerHTML=`<section class="hero"><div class="heroA"><div class="eyebrow">A sua mente é o projeto</div><h1>Construa uma visão de mundo.<br><span style="color:var(--mint)">Uma ideia por dia.</span></h1><p>Filosofia, direito, economia, tecnologia, psicologia e história — numa jornada feita para aprender, lembrar e conectar ideias.</p><div class="row"><button class="btn primary" onclick="study(${next.day})">Retomar jornada ↗</button><button class="btn" onclick="setView('calendar')">Explorar 365 dias</button></div></div><div class="heroB"><div class="eyebrow">Seu núcleo de aprendizagem</div><div class="orb"></div><h3>${esc(next.topic)}</h3><p>Próxima atividade · Dia ${next.day}</p><div class="track"><div class="fill" style="width:${pct()}%"></div></div><p style="font-size:12px">${pct()}% da jornada concluída</p></div></section><section class="constellation"><div class="constellation-head"><div><div class="eyebrow">Navegação por constelações</div><h2>Seu universo de conhecimento</h2><p>Toque em uma estrela para abrir a aula daquele dia. Cada órbita representa uma região da jornada; estrelas verdes são dias concluídos.</p></div><button class="btn" onclick="setView('calendar')">Ver os 365 dias ↗</button></div><div class="map-tools"><div class="row"><button class="btn" onclick="mapZoom(1.25)" aria-label="Aumentar zoom" title="Aumentar zoom">＋ Zoom</button><button class="btn" onclick="mapZoom(.8)" aria-label="Diminuir zoom" title="Diminuir zoom">− Zoom</button><button class="btn" onclick="mapReset()" title="Centralizar e redefinir zoom">◎ Centralizar</button><span class="zoom-readout" id="zoomReadout">100%</span></div><span class="map-caption">Arraste para explorar · use a roda do mouse ou os botões para aproximar · no celular, arraste com um dedo e use os botões de zoom.</span></div><div class="star-map" id="starMap" aria-label="Mapa galáctico interativo dos dias de estudo"></div><div class="map-legend"><span><i class="legend-dot active"></i> Dia selecionado</span><span><i class="legend-dot done"></i> Concluído</span><span><i class="legend-dot"></i> A estudar</span></div><div class="planet-focus" id="planetFocus"><div><small>ESTRELA EM DESTAQUE</small><strong>Escolha um ponto no mapa</strong></div><button class="btn primary" onclick="study(S.active||1)">Abrir aula ↗</button></div><p class="mobile-hint">Dica: toque nas estrelas para explorar. Também é possível buscar qualquer assunto na Jornada.</p></section><div class="metrics"><div class="metric"><small>DIAS CONCLUÍDOS</small><strong>${done()}</strong><small>de ${D.calendar.length}</small></div><div class="metric"><small>TEMPO INVESTIDO</small><strong>${Math.floor(S.minutes/60)}h ${S.minutes%60}m</strong><small>tempo registrado</small></div><div class="metric"><small>SESSÕES</small><strong>${S.sessions}</strong><small>blocos realizados</small></div><div class="metric"><small>LIVROS CONCLUÍDOS</small><strong>${Object.values(S.books).filter(x=>x==="Concluído").length}/${D.books.length}</strong><small>leituras acompanhadas</small></div></div><div class="grid"><section><div class="section"><div class="eyebrow">Sua próxima ação</div><h2>Continue de onde parou</h2></div>${card(next)}<div class="panel"><h3>O método ORBITA</h3><div class="step"><b>1</b><div><strong>Recuperar</strong><p>Tente lembrar três ideias da sessão anterior antes de reler.</p></div></div><div class="step"><b>2</b><div><strong>Compreender</strong><p>Estude um conceito pequeno e explique com suas palavras.</p></div></div><div class="step"><b>3</b><div><strong>Conectar</strong><p>Ligue o conceito a outra disciplina ou a uma situação real.</p></div></div><div class="step"><b>4</b><div><strong>Revisar</strong><p>Retorne amanhã, em 7 dias e em 30 dias.</p></div></div></div></section><section><div class="section"><div class="eyebrow">Ritmo sustentável</div><h2>Mapa semanal</h2><p>Uma área por dia, sem sobrecarga.</p></div><div class="panel">${[["SEG","Filosofia e lógica"],["TER","Direito e política"],["QUA","Economia e finanças"],["QUI","Tecnologia e segurança"],["SEX","Psicologia"],["SÁB","História e cultura"],["DOM","Revisão ou descanso"]].map(x=>`<div class="media"><div><strong>${x[0]}</strong><p>${x[1]}</p></div></div>`).join("")}</div><div class="panel" style="margin-top:12px"><span class="tag">Ciência da aprendizagem</span><p>Não pergunte apenas “entendi?”. Feche o material e tente explicar sem olhar. A recuperação ativa ajuda a fixar o conhecimento.</p></div></section></div>`;
if(document.getElementById("starMap"))mapConstellation();
}else if(v==="calendar"){a.innerHTML=`<div class="eyebrow">O mapa completo</div><h1>Jornada de 365 dias.</h1><p>Pesquise assuntos, filtre por área e abra qualquer sessão. O progresso fica salvo neste navegador.</p><div class="metrics"><div class="metric"><small>PROGRESSO</small><strong>${pct()}%</strong><div class="track"><div class="fill" style="width:${pct()}%"></div></div></div><div class="metric"><small>CONCLUÍDOS</small><strong>${done()}</strong></div><div class="metric"><small>PENDENTES</small><strong>${365-done()}</strong></div><div class="metric"><small>RECURSOS</small><strong>${D.books.length+D.media.length}</strong></div></div><div class="search"><input id="q" class="field" placeholder="Buscar assunto ou atividade..."><select id="area" class="field"><option value="">Todas as áreas</option>${[...new Set(D.calendar.map(x=>x.area))].map(x=>`<option>${esc(x)}</option>`).join("")}</select><select id="st" class="field"><option value="">Todos</option><option value="todo">Pendentes</option><option value="done">Concluídos</option></select></div><div class="list" id="results"></div>`;let update=()=>{let q=$("#q").value.toLowerCase(),ar=$("#area").value,st=$("#st").value;let xs=D.calendar.filter(x=>(!q||`${x.topic} ${x.area} ${x.task} ${x.month}`.toLowerCase().includes(q))&&(!ar||x.area===ar)&&(!st||(st==="done"?S.done[x.day]:!S.done[x.day])));$("#results").innerHTML=xs.slice(0,120).map(x=>`<div class="item" role="button" tabindex="0" onclick="study(${x.day})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();study(${x.day})}"><div class="num">${String(x.day).padStart(2,"0")}</div><div><h3>${esc(x.topic)}</h3><p>${esc(x.month)} · ${esc(x.area)} · ${esc(x.weekday)}</p><p style="color:var(--mint);font-size:11px">${S.done[x.day]?"Concluído · abrir para revisar":"Toque para abrir o roteiro detalhado ↗"}</p></div><button class="status" onclick="event.stopPropagation();study(${x.day})">${S.done[x.day]?"✓ Revisar":"Estudar ↗"}</button></div>`).join("")||`<div class="empty">Nenhum assunto encontrado.</div>`};["q","area","st"].forEach(id=>$("#"+id).addEventListener(id==="q"?"input":"change",update));update();
}else if(v==="study"){study(S.active||1);return}
else if(v==="library"){a.innerHTML=`<div class="eyebrow">Repertório para pensar melhor</div><h1>Biblioteca viva.</h1><p>Leia sem pressa. Anote perguntas e compare as ideias com fontes confiáveis.</p><div class="search"><input class="field" id="bq" placeholder="Buscar livro ou autor..."><select class="field" id="ba"><option value="">Todas as áreas</option>${[...new Set(D.books.map(b=>b.area))].map(x=>`<option>${esc(x)}</option>`).join("")}</select></div><div class="cards" id="books"></div><div class="section"><div class="eyebrow">Fontes primárias</div><h2>Recursos confiáveis</h2></div><div class="panel">${D.resources.map(r=>`<div class="media"><div><strong>${esc(r.name)}</strong><p>${esc(r.area)} · ${esc(r.use)}</p></div><a href="${esc(r.url)}" target="_blank" rel="noopener">Abrir ↗</a></div>`).join("")}</div>`;let update=()=>{let q=$("#bq").value.toLowerCase(),ar=$("#ba").value;let xs=D.books.map((b,i)=>({...b,i})).filter(b=>(!q||`${b.title} ${b.author} ${b.area}`.toLowerCase().includes(q))&&(!ar||b.area===ar));$("#books").innerHTML=xs.map(b=>`<article class="book"><span class="eyebrow">${esc(b.level)} · ${esc(b.when)}</span><h3>${esc(b.title)}</h3><p>${esc(b.author)}<br><br>${esc(b.how)}</p><select class="field" onchange="bookStatus(${b.i},this.value)">${statusOptions(S.books[b.i]||"Não iniciado")}</select></article>`).join("")||`<div class="empty">Nenhum livro encontrado.</div>`};$("#bq").addEventListener("input",update);$("#ba").addEventListener("change",update);update();
}else if(v==="media"){a.innerHTML=`<div class="eyebrow">Cinema como laboratório</div><h1>Assista. Questione. Relacione.</h1><p>Use cada obra para observar argumentos, dilemas e vieses. Filmes e séries não substituem fontes históricas ou materiais didáticos.</p><div class="search"><input class="field" id="mq" placeholder="Buscar obra ou tema..."><select class="field" id="mf"><option value="">Todos os formatos</option>${[...new Set(D.media.map(x=>x.format))].map(x=>`<option>${esc(x)}</option>`).join("")}</select></div><div class="panel" id="medialist"></div>`;let update=()=>{let q=$("#mq").value.toLowerCase(),f=$("#mf").value;let xs=D.media.map((m,i)=>({...m,i})).filter(m=>(!q||`${m.title} ${m.themes} ${m.focus}`.toLowerCase().includes(q))&&(!f||m.format===f));$("#medialist").innerHTML=xs.map(m=>`<div class="media"><div><span class="tag">${esc(m.format)} · ${esc(m.month)}</span><h3 style="margin-top:10px">${esc(m.title)}</h3><p>${esc(m.themes)}</p><p><strong>Observe:</strong> ${esc(m.focus)}</p><textarea class="field note" placeholder="Sua reflexão..." oninput="S.reflections['m${m.i}']=this.value;persistState()">${esc(S.reflections["m"+m.i]||"")}</textarea></div><select class="field" onchange="mediaStatus(${m.i},this.value)">${statusOptions(S.media[m.i]||"Não iniciado")}</select></div>`).join("")||`<div class="empty">Nenhuma obra encontrada.</div>`};$("#mq").addEventListener("input",update);$("#mf").addEventListener("change",update);update();
}else if(v==="notes"){a.innerHTML=`<div class="eyebrow">Pensamento autoral</div><h1>Seu mapa de ideias.</h1><p>Transforme informação em conhecimento próprio. Entre na sua conta para sincronizar registros entre dispositivos.</p><div class="grid"><div class="panel"><h2>Capturar uma ideia</h2><p>Conceito → explicação própria → exemplo → pergunta.</p><input id="nt" class="field" style="width:100%;margin:8px 0" placeholder="Título ou conceito"><textarea id="nb" class="field note" placeholder="Explique com suas palavras..."></textarea><textarea id="nl" class="field note" style="margin:8px 0" placeholder="Conexão com outra área / pergunta"></textarea><button class="btn primary" onclick="addIdea()">Guardar ideia ↗</button></div><div class="panel"><h2>Ideias guardadas</h2><div id="ideas"></div></div></div><div class="section"><div class="eyebrow">Foco</div><h2>Temporizador de estudo</h2></div><div class="panel" style="max-width:450px"><div id="timer" style="font-size:54px;text-align:center;letter-spacing:-.05em">25:00</div><div class="row" style="justify-content:center"><button class="btn primary" id="start" onclick="timerToggle()">Começar</button><button class="btn" onclick="timerSet(25)">25 min</button><button class="btn" onclick="timerSet(10)">10 min</button><button class="btn" onclick="timerReset()">Reiniciar</button></div></div><div class="section"><h2>Seus dados são seus</h2><p>A conta ORBITA sincroniza seus dados na nuvem. Você também pode exportar um backup.</p><div class="row"><button class="btn primary" onclick="backup()">Exportar progresso (.json)</button><label class="btn">Importar backup<input hidden type="file" accept=".json" onchange="restore(event)"></label><button class="btn" onclick="resetAll()">Zerar progresso</button></div></div>`;drawIdeas();}
}
function toggle(n){S.done[n]=!S.done[n];save(S.done[n]?"Dia concluído ✓":"Conclusão desfeita");render("calendar")}
function guideFor(l){
 const a=l.area.toLowerCase(),t=l.topic, isReview=/revisão|revisar/i.test(t);
 const templates=[
  {keys:['direito','política','sistema de justiça','estado'],goal:'Entender a ideia, distinguir conceitos próximos e reconhecer como ela aparece nas instituições brasileiras.',concepts:['Definição e finalidade do conceito','Quem tem autoridade, quais são os limites e quais direitos estão envolvidos','Como o tema aparece na Constituição, nas leis ou nas instituições','Um exemplo real e um possível abuso, conflito ou exceção'],activity:'Consulte uma fonte oficial brasileira (Planalto, órgão público ou tribunal). Encontre um trecho relacionado ao tema, traduza-o para linguagem simples e descreva um caso hipotético em que ele se aplica.',questions:['Qual problema essa regra ou instituição tenta resolver?','Quem decide e com base em qual competência?','Que limite, garantia ou mecanismo de fiscalização existe?'],output:'Um resumo de 120–180 palavras com definição, exemplo brasileiro e fonte oficial consultada.'},
  {keys:['economia','finanças','investimentos'],goal:'Explicar o mecanismo econômico e aplicá-lo a uma decisão cotidiana usando números ou dados.',concepts:['Definição dos termos principais e diferença entre conceitos parecidos','Incentivos, custos, benefícios e trade-offs','Um exemplo numérico simples com unidades explícitas','Limitações: o que o exemplo não prova e quais variáveis ficaram de fora'],activity:'Monte um exemplo com números reais ou fictícios claramente identificados. Mostre a conta passo a passo, altere uma variável e observe como o resultado muda. Se houver dados, confira a fonte e a data.',questions:['Quem ganha, quem paga e quem assume o risco?','Qual é o custo de oportunidade?','Que evidência faria você mudar de conclusão?'],output:'Uma explicação em linguagem simples, uma conta ou gráfico pequeno e uma conclusão com ressalvas.'},
  {keys:['tecnologia','cibersegurança','informática','redes','privacidade','digital'],goal:'Compreender o funcionamento técnico, reconhecer os componentes envolvidos e demonstrar o conceito em ambiente próprio e autorizado.',concepts:['Vocabulário técnico essencial e função de cada componente','Fluxo: entrada → processamento → saída ou evento → evidência → interpretação','Riscos, limites, erros comuns e medidas de proteção','Como verificar o resultado em vez de apenas presumir que funcionou'],activity:'Desenhe um diagrama simples do fluxo e faça um pequeno teste seguro no seu próprio equipamento, em laboratório educacional ou em sistema para o qual você tenha autorização. Registre passos, resultado e limitações; nunca teste sistemas de terceiros sem permissão.',questions:['O que acontece em cada etapa?','Qual evidência observável confirma a hipótese?','Como reproduzir o teste e como evitar dano ou exposição de dados?'],output:'Um mini-relatório com objetivo, ambiente, passos, resultado, evidências e conclusão.'},
  {keys:['psicologia','comportamento','atenção','aprendizagem'],goal:'Descrever o fenômeno psicológico sem confundir uma hipótese com uma certeza e relacioná-lo a um comportamento observável.',concepts:['Definição e teoria principal em termos simples','Fatores individuais e ambientais que podem influenciar o fenômeno','Diferença entre correlação, causalidade e impressão pessoal','Limitações da evidência e explicações alternativas'],activity:'Observe uma situação cotidiana ou analise um caso fictício. Registre o que foi observado separadamente da interpretação; proponha duas explicações possíveis e uma forma ética de distingui-las.',questions:['O que foi observado diretamente e o que estou inferindo?','Que outras causas explicariam o mesmo comportamento?','A ideia se aplica a todos ou depende do contexto?'],output:'Uma ficha com conceito, exemplo observado, hipótese alternativa e uma pergunta aberta.'},
  {keys:['história','cultura','geografia','sociedade'],goal:'Situar o tema no tempo e no espaço, identificar causas e consequências e avaliar as fontes usadas.',concepts:['Período, lugar e atores envolvidos','Contexto anterior e causas de curto e longo prazo','Acontecimentos principais, consequências e grupos afetados','Diferença entre fonte primária, interpretação histórica e memória posterior'],activity:'Construa uma linha do tempo com 4–6 marcos. Compare duas fontes confiáveis, identifique o que ambas confirmam e anote uma divergência ou lacuna.',questions:['O que aconteceu antes e tornou o evento possível?','Quem se beneficiou, quem foi prejudicado e quem ficou de fora dos registros?','Como sabemos disso e quão confiável é a fonte?'],output:'Uma linha do tempo curta e um parágrafo que conecte causa, evento e consequência com fontes.'},
  {keys:['filosofia','lógica','pensamento','argumentação'],goal:'Reconstruir um argumento, testar sua validade e formular uma posição própria com razões explícitas.',concepts:['Tese: o que está sendo defendido','Premissas: quais razões sustentam a tese','Conclusão: o que decorre das premissas','Contraexemplo, pressuposto escondido e diferença entre validade e verdade'],activity:'Escolha uma afirmação sobre o tema. Escreva-a como tese + duas premissas + conclusão. Depois formule a melhor objeção possível e revise a posição sem caricaturar o argumento contrário.',questions:['Qual é a razão mais forte para aceitar a tese?','A conclusão realmente decorre das premissas?','Que contraexemplo enfraqueceria o argumento?'],output:'Um mapa de argumento com tese, premissas, conclusão, objeção e resposta.'},
  {keys:['matemática','estatística','dados','ciência'],goal:'Entender o conceito, interpretar evidências e realizar um exercício verificável sem esconder incertezas.',concepts:['Termos, símbolos, unidades e suposições','Método ou fórmula e por que funciona','Exemplo resolvido passo a passo','Erros comuns, incerteza, escala e limites da conclusão'],activity:'Resolva dois exemplos: um direto e outro com uma pequena variação. Confira o resultado por um segundo método ou estimativa e explique cada etapa como se ensinasse a alguém.',questions:['Quais suposições usei?','O resultado faz sentido em magnitude e unidade?','Que dado ou mudança alteraria a conclusão?'],output:'Dois exercícios resolvidos e uma explicação do método em palavras próprias.'}
 ];
 let z=templates.find(x=>x.keys.some(k=>a.includes(k)));
 if(!z)z={goal:'Compreender o tema com precisão, relacioná-lo ao contexto e transformar a leitura em uma explicação que possa ser verificada.',concepts:['Defina o tema e os termos essenciais; registre o que ele não significa','Identifique os componentes, etapas, atores ou ideias principais','Encontre um exemplo concreto e um contraexemplo ou limite','Compare pelo menos duas fontes e diferencie fato, interpretação e opinião'],activity:'Estude uma fonte introdutória confiável e uma segunda fonte independente. Faça uma página de notas em três colunas: conceito, evidência/exemplo e dúvida. Em seguida, aplique a ideia a um caso concreto e explique por que ela é relevante.',questions:['Qual é a ideia central e como eu a explicaria a um iniciante?','Qual exemplo demonstra o conceito e qual exemplo parece semelhante, mas não se encaixa?','O que ainda não sei e qual fonte ajudaria a responder?'],output:'Uma ficha de estudo com definição, exemplo, aplicação, dúvida pendente e fontes consultadas.'};
 if(isReview){z={...z,goal:'Consolidar a semana sem depender das anotações e localizar lacunas de compreensão.',concepts:['Recupere de memória três conceitos estudados','Explique uma conexão entre duas áreas','Confira as anotações e marque o que esqueceu ou confundiu','Escolha um ponto para revisar em 7 dias'],activity:'Feche os materiais por 5 minutos e escreva tudo que lembrar. Depois confira, corrija com outra cor e crie três cartões de pergunta e resposta.',questions:['O que consigo explicar sem consulta?','Qual conceito confundi e por quê?','Como duas ideias da semana se conectam?'],output:'Um resumo de uma página + três perguntas de revisão.'}}
 return {goal:z.goal,concepts:z.concepts,activity:z.activity,questions:z.questions,output:z.output};
}
let mapView={zoom:1,x:0,y:0,pointers:new Map(),drag:null,pinch:null};
function mapTransform(){const g=document.querySelector('#starMap svg #galaxyWorld');if(!g)return;g.setAttribute('transform',`translate(${mapView.x} ${mapView.y}) translate(450 250) scale(${mapView.zoom}) translate(-450 -250)`);const z=document.getElementById('zoomReadout');if(z)z.textContent=Math.round(mapView.zoom*100)+'%'}
function mapZoom(f){const old=mapView.zoom;mapView.zoom=Math.max(1,Math.min(4.5,old*f));mapTransform()}
function mapReset(){mapView.zoom=1;mapView.x=0;mapView.y=0;mapTransform()}
function mapConstellation(){const el=document.getElementById('starMap');if(!el)return;const W=900,H=500,cx=450,cy=250;let groups=[...new Set(D.calendar.map(x=>x.area))];let colors=['#8fe7ff','#a9a2ff','#d7f77b','#ffb1c8','#ffd38f','#90e5c2','#a8bcff','#f2a9ff'];
// Galaxy distribution: 365 learning stars arranged along multiple logarithmic spiral arms.
let points=D.calendar.map((d,i)=>{let g=groups.indexOf(d.area),arm=g%5,step=Math.floor(i/5),t=.35+step*.105+arm*2*Math.PI/5,r=18+step*2.35;let angle=t;let x=cx+Math.cos(angle)*r*1.48,y=cy+Math.sin(angle)*r*.88;let jitter=((i*17)%13)-6; x+=Math.cos(angle+Math.PI/2)*jitter;y+=Math.sin(angle+Math.PI/2)*jitter;return {...d,x,y,g,arm}});
let arms='';for(let a=0;a<5;a++){let pts=points.filter(p=>p.arm===a).sort((u,v)=>u.day-v.day);let dpath=pts.map((p,j)=>(j?'L':'M')+p.x.toFixed(1)+' '+p.y.toFixed(1)).join(' ');arms+=`<path class="arm" d="${dpath}" stroke="${colors[a%colors.length]}"/>`}
let links='';for(let g=0;g<groups.length;g++){let pts=points.filter(p=>p.g===g).sort((a,b)=>a.day-b.day);for(let j=1;j<pts.length;j++){if(j%3!==0)links+=`<line class="link" x1="${pts[j-1].x}" y1="${pts[j-1].y}" x2="${pts[j].x}" y2="${pts[j].y}"/>`}}
let dust='';for(let i=0;i<180;i++){let angle=i*2.399963,r=22+((i*37)%205),x=cx+Math.cos(angle)*r*1.48,y=cy+Math.sin(angle)*r*.88;dust+=`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${(i%9===0?1.5:.55)}" fill="${colors[i%colors.length]}" opacity="${i%9===0?.65:.38}"/>`}
let nebula=`<g class="nebula"><ellipse cx="320" cy="190" rx="170" ry="52" fill="#7e72ff" transform="rotate(-24 320 190)"/><ellipse cx="570" cy="285" rx="190" ry="48" fill="#42c9ef" transform="rotate(-24 570 285)"/><ellipse cx="460" cy="130" rx="115" ry="34" fill="#ff8ac8" transform="rotate(28 460 130)"/></g>`;
let stars=points.map(p=>`<g class="star ${S.done[p.day]?'done':''} ${S.active===p.day?'active':''}" role="button" tabindex="0" aria-label="Dia ${p.day}: ${esc(p.topic)}" onclick="focusStar(${p.day})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();focusStar(${p.day})}"><circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="${p.day===S.active?4.5:2.1}"/><title>Dia ${p.day}: ${esc(p.topic)} · ${esc(p.area)}</title></g>`).join('');
let labels=groups.map((g,i)=>{let a=(i/groups.length)*Math.PI*2-.5,x=cx+Math.cos(a)*315,y=cy+Math.sin(a)*165;return `<text x="${Math.max(55,Math.min(W-55,x))}" y="${Math.max(18,Math.min(H-10,y))}" fill="${colors[i%colors.length]}" text-anchor="middle" font-size="11" font-weight="600" opacity=".95">${esc(g.length>24?g.slice(0,22)+'…':g)}</text>`}).join('');
el.innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="group" aria-label="Via Láctea de conhecimento com 365 estrelas clicáveis"><defs><radialGradient id="galaxyCore"><stop stop-color="#fffbd7"/><stop offset=".18" stop-color="#d7f77b"/><stop offset=".45" stop-color="#8fe7ff" stop-opacity=".7"/><stop offset="1" stop-color="#a9a2ff" stop-opacity="0"/></radialGradient><radialGradient id="spaceGlow"><stop stop-color="#4b5fd1" stop-opacity=".22"/><stop offset="1" stop-color="#0b1224" stop-opacity="0"/></radialGradient></defs><rect width="900" height="500" fill="url(#spaceGlow)"/>${nebula}<g id="galaxyWorld">${arms}${links}${dust}<ellipse class="orbit" cx="${cx}" cy="${cy}" rx="180" ry="95" transform="rotate(-24 ${cx} ${cy})"/><ellipse class="orbit" cx="${cx}" cy="${cy}" rx="250" ry="130" transform="rotate(-24 ${cx} ${cy})"/><circle cx="${cx}" cy="${cy}" r="62" fill="url(#galaxyCore)" opacity=".95"/><circle cx="${cx}" cy="${cy}" r="5" fill="#fffbd7"/><text x="${cx}" y="${cy+79}" text-anchor="middle" fill="#eaf1ff" font-size="11" letter-spacing="3">ORBITA</text>${stars}${labels}</g></svg>`;
mapView={zoom:1,x:0,y:0,pointers:new Map(),drag:null,pinch:null};mapTransform();
// Pointer controls work with mouse, touch, and stylus. Pinch gestures zoom around the gesture midpoint.
const svg=el.querySelector('svg');svg.addEventListener('wheel',e=>{e.preventDefault();mapZoom(e.deltaY<0?1.12:.89)},{passive:false});
svg.addEventListener('pointerdown',e=>{if(e.target.closest('.star'))return;svg.setPointerCapture(e.pointerId);mapView.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(mapView.pointers.size===1)mapView.drag={x:e.clientX,y:e.clientY,px:mapView.x,py:mapView.y};if(mapView.pointers.size===2){let q=[...mapView.pointers.values()];mapView.pinch={dist:Math.hypot(q[0].x-q[1].x,q[0].y-q[1].y),zoom:mapView.zoom};mapView.drag=null;}});
svg.addEventListener('pointermove',e=>{if(!mapView.pointers.has(e.pointerId))return;mapView.pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});let q=[...mapView.pointers.values()];if(q.length>=2&&mapView.pinch){let d=Math.hypot(q[0].x-q[1].x,q[0].y-q[1].y);mapView.zoom=Math.max(1,Math.min(4.5,mapView.pinch.zoom*d/Math.max(1,mapView.pinch.dist)));mapTransform()}else if(q.length===1&&mapView.drag){let rect=el.getBoundingClientRect();mapView.x=mapView.drag.px+(e.clientX-mapView.drag.x)*900/rect.width;mapView.y=mapView.drag.py+(e.clientY-mapView.drag.y)*500/rect.height;mapTransform()}});
function releaseMapPointer(e){mapView.pointers.delete(e.pointerId);if(mapView.pointers.size<2)mapView.pinch=null;if(mapView.pointers.size===1){let q=[...mapView.pointers.values()][0];mapView.drag={x:q.x,y:q.y,px:mapView.x,py:mapView.y}}else mapView.drag=null}
svg.addEventListener('pointerup',releaseMapPointer);svg.addEventListener('pointercancel',releaseMapPointer);focusStar(S.active||1,false)}
function focusStar(n,open=false){S.active=n;let l=lesson(n),f=document.getElementById('planetFocus');if(f)f.innerHTML=`<div><small>DIA ${l.day} · ${esc(l.area)}</small><strong>${esc(l.topic)}</strong><small>${esc(l.month)} · ${S.done[n]?'Concluído — revise quando quiser':'Sessão de 30–60 min'}</small></div><button class="btn primary" onclick="study(${n})">${S.done[n]?'Reabrir aula':'Estudar este dia'} ↗</button>`;document.querySelectorAll('.star').forEach((e)=>e.classList.remove('active'));let all=document.querySelectorAll('.star');if(all[n-1])all[n-1].classList.add('active');if(open)toast('Dia '+n+' selecionado')}
function study(n){S.active=n;save("Sessão aberta");let l=lesson(n),g=guideFor(l);document.querySelectorAll("[data-v]").forEach(b=>b.classList.toggle("active",b.dataset.v==="study"));let concepts=g.concepts.map(x=>`<li>${esc(x)}</li>`).join(''),questions=g.questions.map(x=>`<li>${esc(x)}</li>`).join('');let earlier=D.calendar.find(x=>x.day===n-1),later=D.calendar.find(x=>x.day===n+1);$("#app").innerHTML=`<div class="eyebrow">Estação de aprendizagem · dia ${l.day} de 365</div><h1>Uma aula, passo a passo.</h1><p>Não é só uma lista de assuntos: este roteiro indica o que compreender, o que praticar e como verificar se aprendeu.</p><div class="grid"><section class="panel"><span class="tag">${esc(l.month)}</span><p>${esc(l.area)} · ${esc(l.weekday)} · 30–60 minutos</p><h2 style="font-size:clamp(26px,4vw,38px)">${esc(l.topic)}</h2><div class="guide-block"><h3>🎯 Objetivo da aula</h3><p style="color:#e1eaff;margin-bottom:0">${esc(g.goal)}</p></div><div class="guide-grid"><div class="guide-block"><h3>📚 O que estudar, exatamente</h3><ul>${concepts}</ul></div><div class="guide-block"><h3>⏱️ Roteiro de 45 minutos</h3><ul><li><b>5 min:</b> escreva o que já sabe e uma pergunta.</li><li><b>15 min:</b> leia/assista a uma fonte introdutória e anote termos-chave.</li><li><b>10 min:</b> consulte uma segunda fonte ou exemplo real.</li><li><b>10 min:</b> faça a atividade prática abaixo.</li><li><b>5 min:</b> feche o material e tente explicar de memória.</li></ul></div></div><div class="guide-block"><h3>🧪 Atividade prática</h3><p style="color:#e1eaff">${esc(g.activity)}</p><p><b>Missão original do dia:</b> ${esc(l.task)}</p></div><div class="guide-block"><h3>🧠 Teste de compreensão</h3><p>Responda sem consultar o material:</p><ul>${questions}</ul></div><div class="guide-block"><h3>📦 Resultado que você deve produzir</h3><p style="color:#e1eaff;margin-bottom:0">${esc(g.output)}</p></div><div class="guide-block"><h3>🔁 Revisão espaçada</h3><ul><li><b>Amanhã:</b> tente recordar a definição em 1 minuto.</li><li><b>Em 7 dias:</b> responda às perguntas sem consultar.</li><li><b>Em 30 dias:</b> aplique o conceito a um novo exemplo.</li></ul></div><p><b>Seu caderno de aula</b> · salvamento automático</p><textarea id="sessionnote" class="field note" placeholder="1. Definição com minhas palavras…\n2. Exemplo/evidência…\n3. Respostas ao teste…\n4. Dúvida que ficou…">${esc(S.notes[n]||'')}</textarea><div class="row"><button class="btn primary" onclick="complete(${n})">${S.done[n]?'Registrar revisão':'Concluir aula e registrar tempo'}</button>${earlier?`<button class="btn" onclick="study(${earlier.day})">← Dia anterior</button>`:''}${later?`<button class="btn" onclick="study(${later.day})">Próximo dia →</button>`:''}<button class="btn" onclick="setView('calendar')">Voltar à jornada</button></div></section><section><div class="panel"><h3>Mapa da sua jornada</h3><div class="study-progress"><h2>${pct()}%</h2><span>${done()} de 365 dias</span></div><div class="track"><div class="fill" style="width:${pct()}%"></div></div><p>Meta: 30–60 minutos. Em um dia corrido, faça a definição e uma pergunta em 10 minutos.</p><button class="btn" onclick="setView('home')">Voltar à constelação ✦</button></div><div class="panel" style="margin-top:12px"><h3>Critério para avançar</h3><p>Você aprendeu o suficiente quando consegue definir o conceito, dar um exemplo e reconhecer ao menos uma limitação sem ler suas notas.</p><h3>Material recomendado</h3><p>${esc(l.notes||'Use uma fonte introdutória confiável e uma fonte independente.')}</p><button class="btn" onclick="setView('library')">Abrir biblioteca ↗</button></div><div class="panel" style="margin-top:12px"><h3>Seu progresso</h3><p>Dia ${n} de 365 · ${S.done[n]?'já concluído':'ainda não concluído'}</p><div class="row"><button class="btn" onclick="focusStar(${n});setView('home')">Ver no mapa</button></div></div></section></div>`;$("#sessionnote").addEventListener("input",e=>{S.notes[n]=e.target.value;persistState()});}
function complete(n){S.notes[n]=$("#sessionnote").value;S.done[n]=true;S.sessions++;let m=prompt("Quantos minutos você estudou nesta sessão?","30");m=Number(m);if(m>0&&m<600)S.minutes+=Math.round(m);save("Sessão registrada ✓");study(Math.min(365,n+1))}
function bookStatus(i,s){S.books[i]=s;save("Leitura atualizada")}function mediaStatus(i,s){S.media[i]=s;save("Obra atualizada")}
function addIdea(){let t=$("#nt").value.trim(),b=$("#nb").value.trim(),l=$("#nl").value.trim();if(!t||!b){toast("Preencha conceito e explicação.");return}S.ideas.unshift({t,b,l,date:new Date().toLocaleDateString("pt-BR")});save("Ideia guardada");$("#nt").value=$("#nb").value=$("#nl").value="";drawIdeas()}
function drawIdeas(){let el=$("#ideas");if(!el)return;el.innerHTML=S.ideas.length?S.ideas.map((x,i)=>`<div class="lesson"><div style="display:flex;justify-content:space-between;gap:8px"><strong>${esc(x.t)}</strong><small>${esc(x.date)}</small></div><p>${esc(x.b)}</p><p style="color:var(--mint)">${esc(x.l)}</p><button class="btn" onclick="S.ideas.splice(${i},1);save('Ideia removida');drawIdeas()">Apagar</button></div>`).join(""):`<div class="empty">Suas ideias aparecem aqui.</div>`}
let ts=1500,ti=null;function drawTimer(){let e=$("#timer");if(e)e.textContent=String(Math.floor(ts/60)).padStart(2,"0")+":"+String(ts%60).padStart(2,"0")}function timerSet(m){clearInterval(ti);ti=null;ts=m*60;drawTimer();if($("#start"))$("#start").textContent="Começar"}function timerReset(){timerSet(25)}function timerToggle(){if(ti){clearInterval(ti);ti=null;$("#start").textContent="Continuar";return}if(ts<=0)ts=1500;$("#start").textContent="Pausar";ti=setInterval(()=>{ts--;drawTimer();if(ts<=0){clearInterval(ti);ti=null;$("#start").textContent="Começar";toast("Bloco concluído! Faça uma pausa.")}},1000)}
function backup(){let b=new Blob([JSON.stringify(S,null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(b);a.download="orbita-progresso.json";a.click();URL.revokeObjectURL(a.href)}
function restore(e){let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{S={...base,...JSON.parse(r.result)};save("Backup importado");render("home")}catch(x){toast("Backup inválido")}};r.readAsText(f)}
function resetAll(){if(confirm("Apagar todo o progresso salvo neste navegador? Faça backup antes, se quiser guardar.")){S={...base};save("Progresso zerado");render("home")}}

