$("#nav").addEventListener("click",e=>{let b=e.target.closest("[data-v]");if(b)setView(b.dataset.v)});$("#date").textContent=new Date().toLocaleDateString("pt-BR",{weekday:"short",day:"2-digit",month:"short",year:"numeric"}).toUpperCase();render("home");
